"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[7838],{2378(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>a,metadata:()=>s,toc:()=>l});var i=n(4848),o=n(8453);const a={title:"Two Kinds of Judgment: The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology",date:new Date("2026-05-10T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"t-ai-writing",article_tags:{zh:["\u4eba\u6a5f\u5354\u4f5c","AI \u8f14\u52a9\u5beb\u4f5c","\u7de8\u8f2f\u5224\u65b7\u529b","\u4e8b\u5be6\u67e5\u6838","\u4e16\u754c\u89c0\u8a2d\u5b9a"],en:["human-ai-collaboration","ai-assisted-writing","editorial-judgment","fact-checking","worldbuilding"]},keywords:["GameVictory","Mirror Realm","Cognitive Position","Diffusive Lock-in","Nintendo"],summary:"Comparing AI collaboration in fiction and non-fiction to argue that different genres demand entirely different forms of human editorial judgment.",status:"published",reading_time:18},r="Two Kinds of Judgment",s={id:"TechNotes/AI \u5354\u4f5c\u5beb\u4f5c\u7684\u771f\u6b63\u96e3\u5ea6\u2014\u2014\u5f9e\u4e00\u672c\u5c0f\u8aaa\u548c\u4e00\u672c\u79d1\u6280\u53f2\u8aaa\u8d77",title:"Two Kinds of Judgment: The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology",description:"I wrote a novel using AI, and then a history of technology.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/AI \u5354\u4f5c\u5beb\u4f5c\u7684\u771f\u6b63\u96e3\u5ea6\u2014\u2014\u5f9e\u4e00\u672c\u5c0f\u8aaa\u548c\u4e00\u672c\u79d1\u6280\u53f2\u8aaa\u8d77.md",sourceDirName:"TechNotes",slug:"/TechNotes/AI \u5354\u4f5c\u5beb\u4f5c\u7684\u771f\u6b63\u96e3\u5ea6\u2014\u2014\u5f9e\u4e00\u672c\u5c0f\u8aaa\u548c\u4e00\u672c\u79d1\u6280\u53f2\u8aaa\u8d77",permalink:"/MythogenEngine/en/docs/TechNotes/AI \u5354\u4f5c\u5beb\u4f5c\u7684\u771f\u6b63\u96e3\u5ea6\u2014\u2014\u5f9e\u4e00\u672c\u5c0f\u8aaa\u548c\u4e00\u672c\u79d1\u6280\u53f2\u8aaa\u8d77",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Two Kinds of Judgment: The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology",date:"2026-05-10T00:00:00.000Z",lang:"en",section:"sober-record",topic:"t-ai-writing",article_tags:{zh:["\u4eba\u6a5f\u5354\u4f5c","AI \u8f14\u52a9\u5beb\u4f5c","\u7de8\u8f2f\u5224\u65b7\u529b","\u4e8b\u5be6\u67e5\u6838","\u4e16\u754c\u89c0\u8a2d\u5b9a"],en:["human-ai-collaboration","ai-assisted-writing","editorial-judgment","fact-checking","worldbuilding"]},keywords:["GameVictory","Mirror Realm","Cognitive Position","Diffusive Lock-in","Nintendo"],summary:"Comparing AI collaboration in fiction and non-fiction to argue that different genres demand entirely different forms of human editorial judgment.",status:"published",reading_time:18},sidebar:"docs",previous:{title:"AI Models Haven't Gotten Dumber\u2014They're Just No Longer Designed for You",permalink:"/MythogenEngine/en/docs/TechNotes/AI \u6a21\u578b\u4e0d\u662f\u8b8a\u7b28\u4e86\uff0c\u662f\u4e0d\u518d\u70ba\u4f60\u800c\u8a2d\u8a08"},next:{title:"Google Is No Longer Designed for You Either: When Free Models Become the Gateway to Enterprise Cloud",permalink:"/MythogenEngine/en/docs/TechNotes/Google \u4e5f\u4e0d\u518d\u70ba\u4f60\u800c\u8a2d\u8a08\uff1a\u7576\u514d\u8cbb\u6a21\u578b\u8b8a\u6210\u4f01\u696d\u96f2\u7aef\u7684\u5165\u53e3"}},h={},l=[{value:"The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology",id:"the-true-difficulty-of-ai-collaborative-writingstarting-from-a-novel-and-a-history-of-technology",level:2},{value:"I. Judgment in a Novel: Could This Person Say This in This Time and Space?",id:"i-judgment-in-a-novel-could-this-person-say-this-in-this-time-and-space",level:2},{value:"II. Judgment in Non-Fiction: What Framework Should Be Used to View This History?",id:"ii-judgment-in-non-fiction-what-framework-should-be-used-to-view-this-history",level:2},{value:"III. Neither Judgment Can Be Outsourced, but the Ways They Fail Are Completely Different",id:"iii-neither-judgment-can-be-outsourced-but-the-ways-they-fail-are-completely-different",level:2},{value:"IV. The History of Technology Isn&#39;t Black and White\u2014But AI Naturally Wants to Turn Gray into Black and White",id:"iv-the-history-of-technology-isnt-black-and-whitebut-ai-naturally-wants-to-turn-gray-into-black-and-white",level:2},{value:"V. The Direction of Rule Evolution is Different",id:"v-the-direction-of-rule-evolution-is-different",level:2},{value:"VI. AI is a Mirror, but the Two Mirrors Reflect Different Things",id:"vi-ai-is-a-mirror-but-the-two-mirrors-reflect-different-things",level:2},{value:"VII. Two Kinds of Difficulty, One Core That Cannot Be Outsourced",id:"vii-two-kinds-of-difficulty-one-core-that-cannot-be-outsourced",level:2}];function d(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"I wrote a novel using AI, and then a history of technology."}),"\n",(0,i.jsx)(t.p,{children:"With the novel, I could feel it when the AI made a mistake.\nWith the technology history, I couldn't."}),"\n",(0,i.jsx)(t.p,{children:"Because it wrapped a flawed judgment inside a logically perfect argument. The rhythm was beautiful, the reasoning rigorous; it looked more like deep analysis than my own first draft."}),"\n",(0,i.jsx)(t.p,{children:"It wasn't until I fished out a counterexample from my own memory\u2014the kind AI can't find via search\u2014that the entire framework collapsed."}),"\n",(0,i.jsx)(t.p,{children:"Two kinds of writing, two kinds of judgment, two entirely different ways to fail."}),"\n",(0,i.jsx)(t.p,{children:"AI amplifies the depth you already possess.\nYour blind spots are its blind spots."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(6972).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.p,{children:"Full text:"}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"two-kinds-of-judgment",children:"Two Kinds of Judgment"})}),"\n",(0,i.jsx)(t.h2,{id:"the-true-difficulty-of-ai-collaborative-writingstarting-from-a-novel-and-a-history-of-technology",children:"The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology"}),"\n",(0,i.jsx)(t.p,{children:"I wrote two books with AI."}),"\n",(0,i.jsxs)(t.p,{children:["The first is a story about an engineer crushed by a workplace system, only seeing the full picture after the fact. The second is ",(0,i.jsx)(t.em,{children:"GameVictory"}),', a Traditional Chinese non-fiction book subtitled "From Pixels to AI: How Entertainment Secretly Reshaped Global Tech Hegemony"\u2014tracing the 40-year history of PC gaming to argue that every major shift in tech hegemony was fundamentally the accidental result of a group of people wanting to play better games.']}),"\n",(0,i.jsx)(t.p,{children:'Both books used AI as a collaborator. Neither was a "tell AI to write, humans revise" model. Both required an evolving set of writing instructions.'}),"\n",(0,i.jsx)(t.p,{children:"But their difficulty structures were completely different."}),"\n",(0,i.jsx)(t.p,{children:'Because the word "judgment" means two completely different things in these two books.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"i-judgment-in-a-novel-could-this-person-say-this-in-this-time-and-space",children:"I. Judgment in a Novel: Could This Person Say This in This Time and Space?"}),"\n",(0,i.jsx)(t.p,{children:'The novel had a writing taboo: "Lin Zhao-ming cannot name abstract concepts in the office." Behind this lies the cognitive design of the whole book. The novel is divided into the office perspective and the study perspective. The protagonist in the office can only feel, be confused, and remember details. Turning feelings into concepts\u2014naming them\u2014is the privilege of the study, an ability only acquired when looking back years later.'}),"\n",(0,i.jsx)(t.p,{children:'If the AI had the protagonist say the words "Persona System" in an office scene, the cognitive arc of the entire book would collapse.'}),"\n",(0,i.jsx)(t.p,{children:"This rule wasn't there from day one. It emerged when I was writing a certain chapter, and the AI produced text that was \"technically flawless, grammatically fluent, and logically sound.\" But reading it, I felt something was wrong. It took me half a day to figure out: the problem wasn't the wording, it was the cognitive position. It's not that the protagonist couldn't say those words; it's that in that time and space, he hadn't yet reached a position where he could."}),"\n",(0,i.jsxs)(t.p,{children:['This is the essence of "judgment" in a novel: ',(0,i.jsx)(t.strong,{children:"the object of judgment is the cognitive position."})," What the character knows, doesn't know, or thinks they know at this exact moment. AI's failure mode is making the character too lucid, naming things too early, having too much agency\u2014because AI naturally tends to clarify the ambiguous. And what a novel needs is exactly to preserve that ambiguity."]}),"\n",(0,i.jsx)(t.p,{children:"One hundred and eight taboos, all doing the same thing: preventing the AI from crossing a cognitive boundary. The direction was locked from day one\u2014to write about how someone crushed by a system sees the full picture only afterward. The rules got more and more detailed, but they always protected the same thing."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"ii-judgment-in-non-fiction-what-framework-should-be-used-to-view-this-history",children:"II. Judgment in Non-Fiction: What Framework Should Be Used to View This History?"}),"\n",(0,i.jsxs)(t.p,{children:["There were also taboos in the writing instructions for ",(0,i.jsx)(t.em,{children:"GameVictory"}),". Five of them: no nostalgic tone, no academic tone, no manual tone, no heartwarming endings, no list-making."]}),"\n",(0,i.jsx)(t.p,{children:'But these five taboos don\'t protect a fixed cognitive position. They protect a moving target\u2014the core argument of each chapter is different, and the boundary of "what counts as a manual tone" changes every time.'}),"\n",(0,i.jsx)(t.p,{children:"The technical details of CUDA's four-layer lock are the core weapon of the argument in Chapter 7. If those same details appeared in Chapter 9 (about Lisa Su), it would be a manual tone\u2014because Chapter 9's argument doesn't need it. AI won't make this distinction on its own. I had to recalibrate the boundary of \"details serving the argument\" before starting each chapter."}),"\n",(0,i.jsxs)(t.p,{children:["But that's not the hardest part. The hardest part is: ",(0,i.jsx)(t.strong,{children:"value judgment in non-fiction writing isn't about protecting a known stance; it's about discovering that the stance itself needs revision during the writing process."})]}),"\n",(0,i.jsx)(t.p,{children:"Let me give a specific example."}),"\n",(0,i.jsxs)(t.p,{children:["Chapter 11 of ",(0,i.jsx)(t.em,{children:"GameVictory"}),' is about Nintendo and Sega. In the fourth draft (v4) of the final chapter, there was a sentence: "Sega and Nintendo\u2014the only two companies that didn\'t establish platform lock-in\u2014one died, and the other lives on an isolated island."']}),"\n",(0,i.jsx)(t.p,{children:"When I wrote this down, I thought it was right. It was neat, powerful, and formed a beautiful contrast with the pattern of the previous ten chapters."}),"\n",(0,i.jsx)(t.p,{children:"Then I remembered it myself: Nintendo embedded the 10NES lockout chip in NES cartridges in 1985\u2014ten years before Microsoft's DirectX. Its licensing system was so draconian that it was unparalleled in its era."}),"\n",(0,i.jsx)(t.p,{children:'The judgment "didn\'t establish platform lock-in" was wrong.'}),"\n",(0,i.jsx)(t.p,{children:'But the correction wasn\'t simply changing "didn\'t" to "did." If Nintendo "had a lock," how was it different from Microsoft\'s DirectX or NVIDIA\'s CUDA? Why did it lock its system for forty years without becoming the infrastructure for tech hegemony?'}),"\n",(0,i.jsxs)(t.p,{children:["This question forced out a brand new analytical framework: ",(0,i.jsx)(t.strong,{children:"Diffusive Lock-in vs. Walled-Garden Lock-in."})]}),"\n",(0,i.jsx)(t.p,{children:"DirectX's lock diffuses outward\u2014from PC games penetrating the entire Windows development ecosystem. CUDA's lock diffuses outward\u2014from gaming GPUs penetrating global AI infrastructure. Nintendo's lock doesn't diffuse outward\u2014the boundary stops at its own platform; it never tried to make its technical standards into industry standards."}),"\n",(0,i.jsxs)(t.p,{children:['This framework wasn\'t found through fact-checking. Fact-checking only told me "Nintendo had a lock." ',(0,i.jsx)(t.strong,{children:'The classification dimension of "diffusive vs. walled-garden" was a value judgment I was forced to make in the process of correcting a factual error: what dimension I chose to view the lock.'})]}),"\n",(0,i.jsx)(t.p,{children:'This judgment changed the entire structure of the final chapter. "Eight variations, one absence" became "Eight diffusions, one walled garden, one unlocked." The counting changed. The mirror paragraphs changed. The hidden spine of the whole book went from one thread to two.'}),"\n",(0,i.jsx)(t.p,{children:"This doesn't happen in a novel. The cognitive framework of a novel is basically stable after the outline is set\u2014you need to protect it, but you don't need to rebuild it during the writing process. A non-fiction framework will be repeatedly remodeled by its own discoveries."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iii-neither-judgment-can-be-outsourced-but-the-ways-they-fail-are-completely-different",children:"III. Neither Judgment Can Be Outsourced, but the Ways They Fail Are Completely Different"}),"\n",(0,i.jsx)(t.p,{children:"When judgment in a novel goes wrong, you can usually feel it."}),"\n",(0,i.jsx)(t.p,{children:'If AI has a character name a concept in the office, you\'ll read it and feel "this is wrong"\u2014even if you can\'t articulate why at first. That intuition of "wrongness" is reliable because you are the author of the story; you know what state this person should be in at this time and space. Your job is to translate that intuition into rules. The process is slow, but the direction is certain.'}),"\n",(0,i.jsx)(t.p,{children:"When judgment in non-fiction goes wrong, sometimes you don't feel it\u2014and AI can't help you either."}),"\n",(0,i.jsx)(t.p,{children:'"Nintendo didn\'t establish platform lock-in"\u2014when this sentence was written down, I thought it was right. It was logically self-consistent, narratively beautiful, and formed a neat contrast with the pattern of the first ten chapters. AI also thought it was right. If I asked AI to "check this paragraph for factual errors," it wouldn\'t trigger any alarms\u2014because in AI\'s knowledge base, the association strength between the words "Nintendo" and "platform lock-in" is far lower than between "Microsoft" and "platform lock-in."'}),"\n",(0,i.jsx)(t.p,{children:"The person who discovered the problem with this sentence was me. Not the AI."}),"\n",(0,i.jsx)(t.p,{children:"I knew there was a 10NES lockout chip in the 1985 NES cartridge. I knew Nintendo's licensing system at the time was so draconian that developers complained bitterly. This is my own domain knowledge\u2014decades of accumulated fundamental understanding of gaming hardware history. Because I knew this, I was able to fish out a counterexample from my own memory when I read \"didn't establish platform lock-in.\""}),"\n",(0,i.jsx)(t.p,{children:"AI can't fish out this counterexample. It's not that it can't search\u2014it's that it doesn't know what to search for. \"Did Nintendo have platform lock-in?\" is a question you only ask when you already doubt the answer. And the premise of doubting is that you yourself first know the 10NES exists."}),"\n",(0,i.jsx)(t.p,{children:"The relationship between NVIDIA's closed-source drivers and Linux gaming is the same structure. Chapter 6 writes about why Valve chose AMD over NVIDIA as the GPU partner for the Steam Deck\u2014the foundation of this judgment is that I knew NVIDIA's Linux drivers are closed-source, AMD's are open-source, and Valve needed end-to-end control of the translation pipeline. AI can help me check the open-source status of GPU drivers, but the causal chain of \"the difference between open and closed source will affect Valve's platform choice\" was built by me. AI won't actively build this connection\u2014because it doesn't know this connection is important."}),"\n",(0,i.jsxs)(t.p,{children:["This is a danger unique to non-fiction writing: ",(0,i.jsx)(t.strong,{children:"A wrong factual premise can support a logically perfect wrong argument. And the more perfect the logic, the less likely you are to doubt the premise."})," AI's fact-checking is only useful if you point it in the right direction. If you yourself don't know Nintendo had 10NES, running a few more rounds of checks won't trigger that problem."]}),"\n",(0,i.jsxs)(t.p,{children:["So what kind of fact-checking can AI help with? The verification of specific numbers. After Chapter 7 (CUDA) was delivered, I knew which numbers needed checking\u2014the release year of CUDA 1.0, the naming lineage of Tesla GPUs, the starting year of cuDNN, the pricing of GeForce 8800 GTX\u2014and then I asked AI to verify them one by one. The result found four errors. These weren't style drift; they were hard errors. But the point is: ",(0,i.jsx)(t.strong,{children:"I have to know what to check first before AI can help me check it."})]}),"\n",(0,i.jsx)(t.p,{children:"The taboo list in a novel is driven by intuition\u2014feels wrong \u2192 clarify \u2192 solidify into a rule. The gatekeeper in non-fiction isn't the AI's checking program, it's the author's own domain knowledge. You know where to doubt, so AI has a direction to check. Where you don't know, AI is just as blind as you are."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iv-the-history-of-technology-isnt-black-and-whitebut-ai-naturally-wants-to-turn-gray-into-black-and-white",children:"IV. The History of Technology Isn't Black and White\u2014But AI Naturally Wants to Turn Gray into Black and White"}),"\n",(0,i.jsxs)(t.p,{children:["There is another kind of judgment in non-fiction writing that is completely different from novels: ",(0,i.jsx)(t.strong,{children:"characterizing the gray areas."})]}),"\n",(0,i.jsx)(t.p,{children:'"Is NVIDIA\'s closed-source strategy good or bad?"'}),"\n",(0,i.jsx)(t.p,{children:'If you ask AI this question, it will give you a balanced answer: "Closed-source has both pros and cons, it depends on the specific context." Technically correct, but completely useless.'}),"\n",(0,i.jsxs)(t.p,{children:["The judgment in ",(0,i.jsx)(t.em,{children:"GameVictory"})," is: NVIDIA's closed-source strategy achieved completely opposite results on two battlefields. In Linux gaming hardware, closed-source made it lose\u2014Valve needed end-to-end control of the translation pipeline, closed-source drivers prevented this, so Valve chose AMD. In AI computing, the same closed-source strategy made it win\u2014CUDA's lock is four layers deep, and no matter how open-source AMD's driver layer is, it can't touch the top three layers."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The same company, the same strategy, two opposite results."}),' This judgment isn\'t "balanced"\u2014it\'s precise. It rejects the moral simplification of "open-source good vs. closed-source bad," but it\'s not a vague two-sided argument either. It explicitly points out: the depth of the lock determines the effect of the strategy.']}),"\n",(0,i.jsx)(t.p,{children:"AI can't make this judgment. Not because it's not smart enough\u2014it's because this judgment requires you to first see through the hidden thread between Chapter 6 and Chapter 7, and that hidden thread only emerges during the writing process. You can't put \"the dual ending of NVIDIA's closed-source strategy\" into the prompt on day one\u2014you have to finish writing Chapter 6 (why Valve chose AMD), then finish writing Chapter 7 (why CUDA couldn't be pried open), before you can look back and see that thread."}),"\n",(0,i.jsx)(t.p,{children:'Novels also have characterizations of gray areas. "Is management lying, or do they genuinely believe their own version?"\u2014it wasn\'t until I wrote Chapter 18 that I discovered the answer is "Neither\u2014their calculation has become instinct, the mask has fused with the face." This judgment is equally precise, and equally something AI cannot do for you.'}),"\n",(0,i.jsx)(t.p,{children:"But the difference between the two lies in this: the gray area in a novel is the grayness of human nature\u2014you rely on your understanding of people. The gray area in non-fiction is the grayness of causality\u2014you rely on your understanding of systems. AI has blind spots for both, but the shapes of the blind spots are different."}),"\n",(0,i.jsx)(t.p,{children:"AI's blind spot when dealing with the grayness of human nature is: it tends to make characters too rational, too self-aware, and too quick to see the situation clearly. The correction direction is to suppress the character's cognition and maintain ambiguity."}),"\n",(0,i.jsx)(t.p,{children:'AI\'s blind spot when dealing with the grayness of causality is: it tends to give a balanced argument that "both sides have a point," avoiding making a judgment. The correction direction is to force it (or more accurately, force yourself) to make a precise characterization\u2014not "it has pros and cons," but "under what conditions is it good, under what conditions is it bad, and what is the difference in those conditions."'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"v-the-direction-of-rule-evolution-is-different",children:"V. The Direction of Rule Evolution is Different"}),"\n",(0,i.jsxs)(t.p,{children:["The taboo list for the novel grew from ten rules to one hundred and eight. The direction of evolution is ",(0,i.jsx)(t.strong,{children:"single-axis deep drilling"}),"\u2014digging finer and finer within the same cognitive framework. The first version's taboo was \"don't let the protagonist know the truth\"\u2014coarse-grained. By rule 108, the taboo had become as fine as \"you cannot write the colleague's financial pressure as fake or self-inflicted\u2014the pressure is real, but its source is a high-leverage choice.\" The direction hasn't changed; the precision has improved."]}),"\n",(0,i.jsxs)(t.p,{children:["The rule evolution direction for ",(0,i.jsx)(t.em,{children:"GameVictory"})," is ",(0,i.jsx)(t.strong,{children:"structural reorganization"}),"."]}),"\n",(0,i.jsx)(t.p,{children:'Writing up to Chapter 6, I discovered that a "lock" isn\'t just a pattern, but has a depth dimension\u2014DirectX is a shallow lock (one API layer, can be translated), CUDA is a deep lock (four layers stacked, impossible to translate). This discovery wasn\'t adding details to an existing framework; it was an upgrade of the framework itself. The pattern tracking table in the outline upgraded from 1D (the variation of "convenience \u2192 lock-in \u2192 monopoly") to 3D (direction of variation \xd7 depth of lock \xd7 dual ending of NVIDIA\'s closed-source strategy).'}),"\n",(0,i.jsx)(t.p,{children:'Then in Chapter 11, the framework of "three kinds of locks, three endings" appeared\u2014diffusive, walled-garden, unlocked\u2014another structural reorganization. The concluding logic of the final chapter thus shifted from a dichotomy of "locked vs. unlocked" to a more analytically deep trichotomy.'}),"\n",(0,i.jsx)(t.p,{children:"Rule evolution in a novel is like sharpening a knife\u2014the same knife, getting sharper and sharper. Rule evolution in non-fiction is like changing maps\u2014you think you're fighting on a plain, but after walking through six chapters, you realize the terrain is 3D and some battlefields are underground."}),"\n",(0,i.jsx)(t.p,{children:'And every time you change maps, it means you have to go back and check if the arguments of all previous chapters have been overturned by the new framework. The discovery in Chapter 6 had to be poured back into Chapter 2\u2014when readers finish Chapter 2, their understanding of a "lock" must be able to support the upgrade in Chapter 7. The discovery in Chapter 11 had to be poured back into the final chapter\u2014the counting had to change, the mirror paragraphs had to change, the final arithmetic of the whole book had to change.'}),"\n",(0,i.jsx)(t.p,{children:"Novels don't need this kind of backflow. The character's cognitive change in Chapter 18 won't overturn the scene in Chapter 3\u2014because the scene in Chapter 3 is fixed on the character's timeline. The timeline in non-fiction doesn't belong to the character\u2014it belongs to the argument. Once the argument is upgraded, the arguments of all chapters must be recalibrated."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"vi-ai-is-a-mirror-but-the-two-mirrors-reflect-different-things",children:"VI. AI is a Mirror, but the Two Mirrors Reflect Different Things"}),"\n",(0,i.jsx)(t.p,{children:"The most important function of AI isn't output; it's reflection. You provide a prompt, AI reflects it back, and by looking at that reflection, you know what's right and what's wrong."}),"\n",(0,i.jsx)(t.p,{children:"This observation is equally true in non-fiction writing\u2014but what the mirror reflects is different."}),"\n",(0,i.jsx)(t.p,{children:"The novel's mirror reflects the gaps in your understanding of people. AI writes a \"technically flawless\" scene, and you read it and feel it's fake\u2014that feeling of \"fakeness\" is the mirror telling you: you haven't fully thought through this character's internal state at this moment."}),"\n",(0,i.jsx)(t.p,{children:'Non-fiction\'s mirror reflects the gaps in your understanding of the system. AI writes a "logically self-consistent" argument, and you read it and feel it\'s shallow\u2014that feeling of "shallowness" is the mirror telling you: you\'ve only seen the surface layer of the causal structure of this history.'}),"\n",(0,i.jsx)(t.p,{children:"For CUDA's four-layer lock in Chapter 7, the initial draft only had two layers (hardware instruction set and library). AI's output made me feel \"right, but not enough.\" That \"not enough\" forced me to think: what else is there that AI hasn't written, and that I myself haven't thought through clearly? And then the third layer (framework binding) and the fourth layer (knowledge binding) were forced out. Especially the fourth layer\u2014\"GPU computing courses at global universities are taught using CUDA, textbooks use CUDA for examples, and CUDA answers on Stack Overflow outnumber ROCm by fifty times\"\u2014this layer isn't a technical lock-in; it's a cognitive lock-in. It changed the weight of the entire argument."}),"\n",(0,i.jsx)(t.p,{children:"AI didn't discover the fourth layer. I didn't discover it through inspiration either. It was because AI's output wasn't good enough, which forced me to pursue \"why isn't it good enough,\" and the process of pursuing pushed me to a place I hadn't originally reached myself."}),"\n",(0,i.jsx)(t.p,{children:"The value of the mirror doesn't lie in what it reflects. It lies in forcing you to face your own blurry parts. On this point, both kinds of writing are the same."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"vii-two-kinds-of-difficulty-one-core-that-cannot-be-outsourced",children:"VII. Two Kinds of Difficulty, One Core That Cannot Be Outsourced"}),"\n",(0,i.jsx)(t.p,{children:"After writing the two books, my conclusion is:"}),"\n",(0,i.jsxs)(t.p,{children:["The distinction between formulas vs. mentalities is just the first layer. The real distinction is: ",(0,i.jsx)(t.strong,{children:"what are you judging?"})]}),"\n",(0,i.jsx)(t.p,{children:"The judgment in a novel is: could this person say this in this time and space? (Cognitive position)\nThe judgment in non-fiction is: what framework should be used to view this history? (Causal structure)"}),"\n",(0,i.jsx)(t.p,{children:"Neither judgment can be outsourced to AI. But they fail in different ways:"}),"\n",(0,i.jsx)(t.p,{children:"AI failure in a novel is style drift\u2014the character is too lucid, names things too early. You can feel it. Correction relies on intuition.\nAI failure in non-fiction has three types\u2014factual errors (you can't feel them), frameworks that are too shallow (you can feel them but need time to pursue), and the characterization of gray areas being flattened (AI naturally tends toward balanced arguments). Correction relies on intuition plus domain knowledge\u2014and only you have the domain knowledge."}),"\n",(0,i.jsx)(t.p,{children:"Rule evolution in a novel is sharpening a knife\u2014direction remains unchanged, precision improves.\nRule evolution in non-fiction is changing maps\u2014the framework itself is remodeled by your own discoveries during the writing process."}),"\n",(0,i.jsx)(t.p,{children:"But the two have a common core that won't change regardless of the subject matter:"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:'You must have an understanding of what you are doing that is deep enough for you to judge whether every AI output is "right" or "close but wrong."'})}),"\n",(0,i.jsx)(t.p,{children:"That judgment cannot be outsourced by any prompt. Whether you are writing a novel or a history of technology."}),"\n",(0,i.jsx)(t.p,{children:'The only difference is that a novel\'s "close but wrong" hides in a character\'s line of dialogue. The history of technology\'s "close but wrong" might hide in a year you thought was correct, a framework you thought was self-consistent, or a sentence you thought was a fact but is actually a value judgment.'}),"\n",(0,i.jsx)(t.p,{children:"The latter is more dangerous. Because it doesn't trigger intuition\u2014and AI is just as blind as you are."}),"\n",(0,i.jsxs)(t.p,{children:["So AI collaboration in non-fiction has one more prerequisite than a novel: ",(0,i.jsx)(t.strong,{children:"you yourself must understand it first."})," It's not \"understanding how to use AI\"; it's understanding the domain you are writing about\u2014understanding it well enough that you can fish out a counterexample from your memory that AI won't search for you, understanding it well enough to know which numbers need checking and which causal chains need doubting. AI's checking ability is only useful when you point it in the right direction. The direction itself is determined by your decades of fundamental understanding."]}),"\n",(0,i.jsx)(t.p,{children:"This isn't a problem of discipline. Discipline can help you check a few more numbers after you submit the draft. But a question like \"did Nintendo actually have platform lock-in?\" can't be found through discipline\u2014only if you yourself know the 10NES exists will you ask this question."}),"\n",(0,i.jsxs)(t.p,{children:["So the final conclusion is sharper than the first article: AI collaboration isn't just \"judgment cannot be outsourced.\" It's that ",(0,i.jsx)(t.strong,{children:"domain knowledge cannot be outsourced"}),". And domain knowledge isn't something you get by reading a few articles\u2014it's what you have after soaking in that domain for decades, making mistakes, correcting your understanding, and accumulating a set of intuitions."]}),"\n",(0,i.jsx)(t.p,{children:"AI amplifies your existing judgment. However deep you are, that's how far it can help you go. Your blind spots are its blind spots."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"The author wrote a literary novel and a book on the history of technology using AI tools. In both projects, AI served as a mirror, a draft generator, and a quality check tool. All creative decisions and value judgments were made by the author."})})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},6972(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_dvbyj9dvbyj9dvby-5c01b419cc5cd4ebd278ba6e4e26afa3.png"},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(6540);const o={},a=i.createContext(o);function r(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);